cat > hosts.go <<'EOF'
package main

import (
    "bufio"
    "fmt"
    "io"
    "net"
    "os"
    "regexp"
    "strings"
)

const divider = "##################################################################"
const managedNotice = "# Content under this line is handled by hostctl. DO NOT EDIT."

type HostRow struct {
    Profile string
    Status string
    IP string
    Host string
}

type BaseLine struct {
    Text string
    IP string
    Host string
    Off bool
}

type IPGroup struct {
    IP string
    Hosts []string
}

type Profile struct {
    Name string
    Off bool
    Groups []*IPGroup
}

type Hosts struct {
    Base []BaseLine
    Names []string
    Profiles map[string]*Profile
}

var profileRE = regexp.MustCompile(`# profile.(on|off)\s+([a-z0-9_.\-\s]+)`)

func canonicalIP(s string) string {
    ip := net.ParseIP(s)
    if ip == nil { return "" }
    return ip.String()
}

// An entry can be commented out. Comments elsewhere terminate the list of names.
func parseEntry(line string) (string, []string) {
    line = strings.TrimSpace(line)
    fields := strings.Fields(line)
    if len(fields) > 0 && fields[0] == "#" {
        line = strings.TrimSpace(line[1:])
    }
    if i := strings.IndexByte(line, '#'); i >= 0 { line = line[:i] }
    fields = strings.Fields(line)
    if len(fields) < 2 { return "", nil }
    ip := canonicalIP(fields[0])
    if ip == "" { return "", nil }
    return ip, fields[1:]
}

func newHosts() *Hosts { return &Hosts{Profiles: make(map[string]*Profile)} }

func readHosts(path string) (*Hosts, error) {
    f, err := os.Open(path)
    if err != nil { return nil, err }
    defer f.Close()
    return parseHosts(f), nil
}

func parseHosts(r io.Reader) *Hosts {
    h := newHosts()
    scanner := bufio.NewScanner(r)
    var current *Profile
    for scanner.Scan() {
        raw := scanner.Text()
        text := strings.TrimSpace(raw)
        if m := profileRE.FindStringSubmatch(text); m != nil {
            name := strings.TrimSpace(m[2])
            current = &Profile{Name: name, Off: m[1] == "off"}
            h.Names = append(h.Names, name)
            h.Profiles[name] = current
            continue
        }
        if strings.HasPrefix(text, "# end") {
            current = nil
            continue
        }
        if text == divider || text == managedNotice { continue }
        ip, names := parseEntry(raw)
        if current != nil {
            if ip != "" { current.Add(ip, names) }
            continue
        }
        if text == "" && len(h.Base) > 0 && h.Base[len(h.Base)-1].Text == "" {
            continue
        }
        b := BaseLine{Text: text}
        if ip != "" {
            b.IP, b.Host, b.Off = ip, names[0], strings.HasPrefix(raw, "#")
        }
        h.Base = append(h.Base, b)
    }
    return h
}

func (p *Profile) Add(ip string, names []string) {
    var group *IPGroup
    for _, g := range p.Groups {
        if g.IP == ip { group = g; break }
    }
    if group == nil {
        group = &IPGroup{IP: ip}
        p.Groups = append(p.Groups, group)
    }
    for _, name := range names {
        found := false
        for _, n := range group.Hosts { if n == name { found = true; break } }
        if !found { group.Hosts = append(group.Hosts, name) }
    }
}

func (h *Hosts) Ensure(name string, replace bool) *Profile {
    p, exists := h.Profiles[name]
    if !exists || replace {
        p = &Profile{Name: name}
        h.Profiles[name] = p
        if !exists { h.Names = append(h.Names, name) }
    }
    return p
}

func (p *Profile) Load(r io.Reader) {
    s := bufio.NewScanner(r)
    for s.Scan() {
        ip, names := parseEntry(s.Text())
        if ip != "" { p.Add(ip, names) }
    }
}

func (p *Profile) Count() int {
    n := 0
    for _, g := range p.Groups { n += len(g.Hosts) }
    return n
}

func (h *Hosts) Remove(name string) {
    delete(h.Profiles, name)
    names := make([]string, 0, len(h.Names))
    for _, n := range h.Names { if n != name { names = append(names, n) } }
    h.Names = names
}

func (p *Profile) RemoveDomains(names []string) {
    for _, g := range p.Groups {
        remaining := make([]string, 0, len(g.Hosts))
        for _, n := range g.Hosts { if !contains(names, n) { remaining = append(remaining, n) } }
        g.Hosts = remaining
    }
}

func (h *Hosts) Encode() string {
    var b strings.Builder
    end := len(h.Base)
    for end > 0 && h.Base[end-1].Text == "" { end-- }
    for _, l := range h.Base[:end] {
        if l.IP != "" {
            if l.Off { b.WriteString("# ") }
            fmt.Fprintf(&b, "%s %s\n", l.IP, l.Host)
        } else {
            b.WriteString(l.Text)
            b.WriteByte('\n')
        }
    }
    fmt.Fprintf(&b, "\n%s\n%s\n%s\n", divider, managedNotice, divider)
    for _, name := range h.Names {
        if name == "default" { continue }
        p := h.Profiles[name]
        if p == nil { continue }
        status := "on"
        prefix := ""
        if p.Off { status, prefix = "off", "# " }
        fmt.Fprintf(&b, "\n# profile.%s %s\n", status, name)
        for _, g := range p.Groups {
            for _, domain := range g.Hosts { fmt.Fprintf(&b, "%s%s %s\n", prefix, g.IP, domain) }
        }
        b.WriteString("# end\n")
    }
    return b.String()
}

func (h *Hosts) Write(path string) error {
    return os.WriteFile(path, []byte(h.Encode()), 0644)
}

func contains(values []string, val string) bool {
    for _, v := range values { if v == val { return true } }
    return false
}

func statusString(off bool) string {
    if off { return "off" }
    return "on"
}

func (h *Hosts) Rows(names []string, mode string) []HostRow {
    var rows []HostRow
    selected := func(n string) bool { return len(names) == 0 || contains(names, n) }
    if mode != "status" && selected("default") {
        for _, l := range h.Base {
            if l.IP != "" { rows = append(rows, HostRow{"default", statusString(l.Off), l.IP, l.Host}) }
        }
    }
    for _, name := range h.Names {
        p := h.Profiles[name]
        if p == nil || !selected(name) { continue }
        if mode == "status" {
            if name != "default" { rows = append(rows, HostRow{name, statusString(p.Off), "", ""}) }
            continue
        }
        if mode == "enabled" && p.Off { continue }
        if mode == "disabled" && !p.Off { continue }
        for _, g := range p.Groups {
            for _, domain := range g.Hosts { rows = append(rows, HostRow{name, statusString(p.Off), g.IP, domain}) }
        }
    }
    return rows
}
EOF"}

