{"command":"cat > cli.go <<'EOF'
package main

import (
    "encoding/csv"
    "fmt"
    "strconv"
    "strings"
    "time"
)

type Options struct {
    Command string
    Args []string
    HostFile string
    Out string
    Columns []string
    Quiet bool
    Raw bool
    NoColor bool
    All bool
    Only bool
    Wait time.Duration
    From string
    IP string
    Path string
    Domain string
    Network string
    ComposeFile string
    ProjectName string
    Prefix bool
    Help bool
    Version bool
}

type flagSpec struct { name, short, kind string }
var globals = []flagSpec{
    {"column", "c", "strings"}, {"host-file", "", "string"},
    {"no-color", "", "bool"}, {"out", "o", "string"},
    {"quiet", "q", "bool"}, {"raw", "", "bool"},
}
var commands = []string{"add", "backup", "disable", "enable", "help", "list", "remove", "replace", "restore", "status", "sync", "toggle"}

func localFlags(command string) []flagSpec {
    fs := []flagSpec{{"help", "h", "bool"}}
    switch command {
    case "": fs = append(fs, flagSpec{"version", "v", "bool"})
    case "add", "replace": fs = append(fs, flagSpec{"from", "f", "string"})
    case "restore": fs = append(fs, flagSpec{"from", "", "string"})
    case "backup": fs = append(fs, flagSpec{"path", "", "string"})
    case "add domains": fs = append(fs, flagSpec{"ip", "", "string"})
    }
    if command == "enable" || command == "disable" || command == "remove" {
        fs = append(fs, flagSpec{"all", "", "bool"})
    }
    if command == "enable" || command == "disable" {
        fs = append(fs, flagSpec{"only", "", "bool"})
    }
    if command == "enable" || command == "disable" || command == "toggle" || command == "add" || strings.HasPrefix(command, "add ") || command == "sync" || strings.HasPrefix(command, "sync ") {
        fs = append(fs, flagSpec{"wait", "w", "duration"})
    }
    if strings.HasPrefix(command, "sync ") {
        fs = append(fs, flagSpec{"domain", "d", "string"}, flagSpec{"network", "", "string"})
        if command == "sync docker-compose" {
            fs = append(fs, flagSpec{"compose-file", "", "string"}, flagSpec{"project-name", "", "string"}, flagSpec{"prefix", "", "bool"})
        }
    }
    return fs
}

func childCommand(parent, name string) string {
    if parent == "" {
        if name == "rm [profiles] [flags]" { return "remove" }
        if contains(commands, name) { return name }
    }
    if parent == "add" || parent == "remove" {
        if name == "domains" || name == "domain [profile] [domains] [flags]" { return parent+" domains" }
    }
    if parent == "list" {
        switch name {
        case "enabled", "on": return "list enabled"
        case "disabled", "off": return "list disabled"
        }
    }
    if parent == "sync" && (name == "docker" || name == "docker-compose") { return parent+" "+name }
    return ""
}

func findLong(fs []flagSpec, name string) (flagSpec, bool) {
    for _, f := range fs { if f.name == name { return f, true } }
    return flagSpec{}, false
}
func findShort(fs []flagSpec, c string) (flagSpec, bool) {
    for _, f := range fs { if f.short != "" && f.short == c { return f, true } }
    return flagSpec{}, false
}

// Command discovery skips flags; command-local flags are subsequently parsed
// against the selected leaf, just like global flags placed before the command.
func discover(args []string) (string, map[int]bool, string) {
    command := ""
    removed := make(map[int]bool)
    looking := true
    for i := 0; i < len(args); i++ {
        s := args[i]
        if s == "--" { break }
        if strings.HasPrefix(s, "--") {
            p := strings.SplitN(s[2:], "=", 2)
            if len(p) == 2 { continue }
            fs := append(append([]flagSpec{}, globals...), localFlags(command)...)
            f, ok := findLong(fs, p[0])
            // Built-in help/version flags are added at execution time.
            if f.name == "help" || f.name == "version" { ok = false }
            if !ok || f.kind != "bool" { i++ }
            continue
        }
        if strings.HasPrefix(s, "-") && s != "-" {
            if len(s) == 2 {
                fs := append(append([]flagSpec{}, globals...), localFlags(command)...)
                f, ok := findShort(fs, s[1:])
                if f.name == "help" || f.name == "version" { ok = false }
                if !ok || f.kind != "bool" { i++ }
            }
            continue
        }
        if !looking { continue }
        next := childCommand(command, s)
        if next != "" {
            command = next
            removed[i] = true
            if command == "help" { looking = false }
        } else {
            if command == "" { return command, removed, s }
            looking = false
        }
    }
    return command, removed, ""
}

func parseOptions(args []string, cwd string) (*Options, error) {
    cmd, removed, unknown := discover(args)
    if unknown != "" { return nil, unknownCommand(unknown) }
    o := &Options{Command: cmd, HostFile: "/etc/hosts", Out: "table", Wait: -1, IP: "127.0.0.1", Path: cwd, Domain: "loc"}
    fs := append(append([]flagSpec{}, globals...), localFlags(cmd)...)
    columnChanged := false
    set := func(f flagSpec, value string) error {
        var b bool
        var d time.Duration
        var list []string
        var err error
        switch f.kind {
        case "bool": b, err = strconv.ParseBool(value)
        case "duration": d, err = time.ParseDuration(value)
        case "strings":
            if value != "" { list, err = csv.NewReader(strings.NewReader(value)).Read() }
        }
        if err != nil {
            display := "--"+f.name
            if f.short != "" { display = "-"+f.short+", "+display }
            return fmt.Errorf("invalid argument %q for %q flag: %v", value, display, err)
        }
        switch f.name {
        case "help": o.Help = b
