package main

import (
    "fmt"
    "io"
    "os"
    "os/signal"
    "path/filepath"
    "strings"
    "syscall"
    "time"
    "unsafe"
)

type Application struct { options *Options; cwd string; color bool }

func isTerminal() bool {
    var termios syscall.Termios
    _, _, err := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(), syscall.TCGETS, uintptr(unsafe.Pointer(&termios)))
    return err == 0
}

func colorEnabled() bool { return isTerminal() && os.Getenv("TERM") != "dumb" && os.Getenv("NO_COLOR") == "" }

func logLine(symbol, color, text string, enabled bool) {
    if enabled { symbol = "\x1b[1;"+color+"m"+symbol+"\x1b[0m" }
    fmt.Printf("[%s] %s\n", symbol, text)
}

func (a *Application) info(text string) {
    if !a.options.Quiet { logLine("ℹ", "36", text+"\n", a.color) }
}
func (a *Application) success(text string) {
    if !a.options.Quiet { logLine("✔", "32", text+"\n", a.color) }
}

func (a *Application) showHelp(command string, stderr bool, usageOnly bool) {
    text := helpText[command]
    text = strings.ReplaceAll(text, "{{CWD}}", a.cwd)
    if usageOnly {
        if i := strings.Index(text, "Usage:"); i >= 0 { text = text[i:] }
        var lines []string
        for _, line := range strings.Split(text, "\n") {
            if strings.Contains(line, "--help ") || strings.Contains(line, "--version ") { continue }
            lines = append(lines, line)
        }
        text = strings.Join(lines, "\n")
    }
    if stderr { fmt.Fprint(os.Stderr, text) } else { fmt.Print(text) }
}

func (a *Application) display(names []string, mode string, evenQuiet bool) error {
    if a.options.Quiet && !evenQuiet { return nil }
    h, err := readHosts(a.options.HostFile)
    if err != nil { return err }
    rows := h.Rows(names, mode)
    fmt.Print(renderRows(rows, a.options.Columns, a.options.Out, a.options.Raw, mode == "status"))
    return nil
}

func (a *Application) run() error {
    o := a.options
    if o.Version { fmt.Println("hostctl version dev"); return nil }
    if o.Help { a.showHelp(o.Command, false, false); return nil }
    if o.Command == "help" {
        cmd := ""
        for _, name := range o.Args {
