package main

import (
    "encoding/json"
    "fmt"
    "regexp"
    "strings"
    "unicode"
)

// Terminal cells need display widths rather than byte lengths. Combining marks
// consume no space, while the common full-width East Asian ranges consume two.
func displayWidth(s string) int {
    n := 0
    inEscape := false
    for _, r := range s {
        if r == 27 { inEscape = true; continue }
        if inEscape { if r == 'm' { inEscape = false }; continue }
        if r == '\n' || r == '\r' || r == 0 || unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Me, r) || r == 0x200d { continue }
        if r < 32 || (r >= 0x7f && r < 0xa0) { continue }
        if r >= 0x1100 && (r <= 0x115f || r == 0x2329 || r == 0x232a || (r >= 0x2e80 && r <= 0xa4cf && r != 0x303f) || (r >= 0xac00 && r <= 0xd7a3) || (r >= 0xf900 && r <= 0xfaff) || (r >= 0xfe10 && r <= 0xfe19) || (r >= 0xfe30 && r <= 0xfe6f) || (r >= 0xff00 && r <= 0xff60) || (r >= 0xffe0 && r <= 0xffe6) || (r >= 0x1f300 && r <= 0x1faff) || (r >= 0x20000 && r <= 0x3fffd)) { n += 2 } else { n++ }
    }
    return n
}

func padding(n int) string { if n < 0 { return "" }; return strings.Repeat(" ", n) }
func alignLeft(s string, n int) string { return s + padding(n-displayWidth(s)) }
func alignRight(s string, n int) string { return padding(n-displayWidth(s)) + s }
func alignCenter(s string, n int) string {
    extra := n-displayWidth(s)
    return padding(extra/2)+s+padding(extra-extra/2)
}

var numberRE = regexp.MustCompile(`^[-+]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)$`)

func headerName(s string) string {
    return strings.ToUpper(strings.ReplaceAll(s, "_", " "))
}

func wrapCell(s string, limit int) []string {
    var lines []string
    for _, original := range strings.Split(s, "\n") {
        if displayWidth(original) <= limit { lines = append(lines, original); continue }
        words := strings.Fields(original)
        current := ""
        for _, w := range words {
            if current == "" { current = w } else if displayWidth(current)+1+displayWidth(w) <= limit { current += " "+w } else { lines = append(lines, current); current = w }
        }
        if current != "" { lines = append(lines, current) }
    }
    if len(lines) == 0 { return []string{""} }
    return lines
}

func renderRows(rows []HostRow, columns []string, output string, raw bool, status bool) string {
    if raw { output = "raw" }
    if output == "json" {
        b, _ := json.Marshal(rows)
        return string(b)+"\n"
    }
    if len(rows) == 0 { return "" }
    if status { columns = []string{"profile", "status"} }
    if len(columns) == 0 { columns = []string{"profile", "status", "ip", "domain"} }
    headers := make([]string, len(columns))
    widths := make([]int, len(columns))
    for i, c := range columns { headers[i] = headerName(c); widths[i] = displayWidth(headers[i]) }
    cells := make([][]string, len(rows))
    for i, row := range rows {
        for _, c := range columns {
            switch c {
            case "profile": cells[i] = append(cells[i], row.Profile)
            case "status": cells[i] = append(cells[i], row.Status)
            case "ip": cells[i] = append(cells[i], row.IP)
            case "domain": cells[i] = append(cells[i], row.Host)
            }
        }
    }
    if len(cells[0]) == 0 { return "" }
    isTable := output != "raw" && output != "markdown"
    wrapped := make([][][]string, len(cells))
    for i, row := range cells {
        wrapped[i] = make([][]string, len(row))
        for j, cell := range row {
            lines := []string{cell}
            if isTable { lines = wrapCell(cell, 30) }
            wrapped[i][j] = lines
            for _, line := range lines { if displayWidth(line) > widths[j] { widths[j] = displayWidth(line) } }
            if isTable && displayWidth(cell) > 30 {
                // Wrapping reserves the requested column width, even when the
                // words in each individual wrapped line leave some room.
                if widths[j] < 30 { widths[j] = 30 }
            }
        }
    }
    var out strings.Builder
    if output == "raw" {
        for i, s := range headers {
            if i > 0 { out.WriteByte('\t') }
            out.WriteString(alignLeft(strings.TrimSpace(s), widths[i]))
        }
        out.WriteString(" \n")
        for _, row := range cells {
            for j, s := range row { out.WriteString(alignLeft(s, widths[j])); out.WriteByte('\t') }
            out.WriteByte('\n')
        }
        return out.String()
    }
    border := func() {
        delim := "+"
        if output == "markdown" { delim = "|" }
        out.WriteString(delim)
        for _, w := range widths { out.WriteString(strings.Repeat("-", w+2)); out.WriteString(delim) }
        out.WriteByte('\n')
    }
    if output != "markdown" { border() }
    out.WriteByte('|')
    for i, s := range headers { fmt.Fprintf(&out, " %s |", alignCenter(strings.TrimSpace(s), widths[i])) }
    out.WriteByte('\n')
    border()
    for i, row := range wrapped {
        if i > 0 && !status && rows[i].Profile != rows[i-1].Profile { border() }
        lines := 1
        for _, v := range row { if len(v) > lines { lines = len(v) } }
        for line := 0; line < lines; line++ {
            out.WriteByte('|')
            for j, c := range row {
                s := ""
                if line < len(c) { s = c[line] }
                formatted := alignLeft(s, widths[j])
                if numberRE.MatchString(s) { formatted = alignRight(s, widths[j]) }
                fmt.Fprintf(&out, " %s |", formatted)
            }
            out.WriteByte('\n')
        }
    }
    if output != "markdown" { border() }
    return out.String()
}
EOF
