package main

import (
    "context"
    "encoding/json"
    "fmt"
    "io"
    "net"
    "net/http"
    "net/url"
    "os"
    "path/filepath"
    "strings"
    "time"
)

type dockerEndpoint struct {
    IPAddress string
    NetworkID string
}

type dockerContainer struct {
    Names []string
    NetworkSettings struct { Networks map[string]dockerEndpoint }
}

type dockerNetwork struct { ID, Name string }

type dockerConnection struct {
    Host string
    URL string
    Version string
    Client *http.Client
}

func connectDocker() (*dockerConnection, error) {
    host := os.Getenv("DOCKER_HOST")
    if host == "" { host = "unix:///var/run/docker.sock" }
    parts := strings.SplitN(host, "://", 2)
    if len(parts) != 2 { return nil, fmt.Errorf("unable to parse docker host `%s`", host) }
    tr := &http.Transport{}
    baseURL := "http://"+parts[1]
    switch parts[0] {
    case "unix":
        path := parts[1]
        baseURL = "http://api.moby.localhost"
        tr.DialContext = func(ctx context.Context, _, _ string) (net.Conn, error) {
            return (&net.Dialer{Timeout: 5*time.Second}).DialContext(ctx, "unix", path)
        }
    case "tcp":
        tr.DialContext = (&net.Dialer{Timeout: 5*time.Second}).DialContext
    default:
        return nil, fmt.Errorf("unable to parse docker host `%s`", host)
    }
    ver := os.Getenv("DOCKER_API_VERSION")
    if ver == "" { ver = "1.42" }
    return &dockerConnection{Host:host, URL:baseURL, Version:ver, Client:&http.Client{Transport:tr, Timeout:10*time.Second}},nil
}

func (d *dockerConnection) get(path string, target interface{}) error {
    response, err := d.Client.Get(d.URL+"/v"+d.Version+path)
    if err != nil { return fmt.Errorf("Cannot connect to the Docker daemon at %s. Is the docker daemon running?", d.Host) }
    defer response.Body.Close()
    content, err := io.ReadAll(response.Body)
    if err != nil { return err }
    if response.StatusCode < 200 || response.StatusCode >= 400 {
        var message struct { Message string }
        json.Unmarshal(content, &message)
        if message.Message == "" { message.Message = strings.TrimSpace(string(content)) }
        return fmt.Errorf("Error response from daemon: %s", message.Message)
    }
    return json.Unmarshal(content, target)
}

func (a *Application) sync() error {
    o := a.options
    var composeText []byte
    composePath := o.ComposeFile
    if o.Command == "sync docker-compose" {
