{"command":"cat > completion.go <<'EOF'
package main

import (
    "fmt"
    "os"
    "regexp"
    "sort"
    "strings"
)

type completionItem struct { Name, Description string }

func commandItems(command string) []completionItem {
    var result []completionItem
    inside := false
    for _, line := range strings.Split(helpText[command], "\n") {
        if line == "Available Commands:" { inside = true; continue }
        if !inside { continue }
        if strings.TrimSpace(line) == "" { break }
        trimmed := strings.TrimSpace(line)
        parts := strings.SplitN(trimmed, " ", 2)
        if len(parts) == 2 { result = append(result, completionItem{parts[0], strings.TrimSpace(parts[1])}) }
    }
    return result
}

var helpFlagRE = regexp.MustCompile(`^\s*(?:-\w,\s*)?--([a-z-]+)(?: (?:string|strings|duration))?\s{2,}(.+)$`)

func flagDescriptions(command string) map[string]string {
    result := make(map[string]string)
    for _, line := range strings.Split(helpText[command], "\n") {
        if m := helpFlagRE.FindStringSubmatch(line); m != nil {
            desc := m[2]
            if i := strings.LastIndex(desc, " (default "); i >= 0 { desc = desc[:i] }
            result[m[1]] = desc
        }
    }
    return result
}

func completionFlags(command string) []flagSpec {
    locals := localFlags(command)
    inherited := append([]flagSpec{}, globals...)
    // wait is inherited on child commands of add and sync.
    if strings.HasPrefix(command, "add ") || strings.HasPrefix(command, "sync ") {
        inherited = append(inherited, flagSpec{"wait","w","duration"})
        tmp := locals[:0]
        for _, f := range locals { if f.name != "wait" { tmp = append(tmp,f) } }
        locals = tmp
    }
    sort.Slice(locals,func(i,j int)bool{return locals[i].name<locals[j].name})
    if command == "" {
        inherited = append(inherited,locals...)
        sort.Slice(inherited,func(i,j int)bool{return inherited[i].name<inherited[j].name})
        return inherited
    }
    return append(inherited,locals...)
}

func (a *Application) complete() error {
    args := a.options.Args
    if len(args) == 0 { return fmt.Errorf("requires at least 1 arg(s), only received 0") }
    partial := args[len(args)-1]
    preceding := args[:len(args)-1]
    if len(preceding)>0 && preceding[0]=="help" { preceding=preceding[1:] }
    cmd, removed, unknown := discover(preceding)
    directive := 0
    var items []completionItem
    finish := func() error {
        for _, item := range items {
            if a.options.Command == "__completeNoDesc" || item.Description == "" { fmt.Println(item.Name) } else { fmt.Printf("%s\t%s\n",item.Name,item.Description) }
        }
        fmt.Printf(":%d\n",directive)
        label := "ShellCompDirectiveDefault"
        if directive==4 { label="ShellCompDirectiveNoFileComp" }
        fmt.Fprintln(os.Stderr,"Completion ended with directive: "+label)
        return nil
    }
    if unknown!="" {
        fmt.Fprintf(os.Stderr,"[Debug] [Error] Unable to find a command for arguments: %v\n",preceding)
        return finish()
    }
    fs:=completionFlags(cmd)
    flagsOnly:=make([]string,0,len(preceding))
    for i,s:=range preceding { if !removed[i] { flagsOnly=append(flagsOnly,s) } }
    changed:=make(map[string]bool)
    needValue:=false
    afterDash:=false
    for i:=0;i<len(flagsOnly);i++ {
        word:=flagsOnly[i]
        if word=="--" { afterDash=true;break }
        if strings.HasPrefix(word,"--") {
            parts:=strings.SplitN(word[2:],"=",2)
            f,ok:=findLong(fs,parts[0]);if !ok { continue }
            changed[f.name]=true
            if len(parts)==1 && f.kind!="bool" {
                if i==len(flagsOnly)-1 { needValue=true } else { i++ }
            }
        } else if strings.HasPrefix(word,"-") && word!="-" {
            left:=word[1:]
            for len(left)>0 {
                f,ok:=findShort(fs,left[:1]);left=left[1:]
                if !ok { break }
                changed[f.name]=true
                if f.kind!="bool" {
                    if left=="" { if i==len(flagsOnly)-1 { needValue=true } else { i++ } }
                    break
                }
                if strings.HasPrefix(left,"=") { break }
            }
        }
    }
    if needValue { return finish() }
    parsed, err:=parseOptions(preceding,a.cwd)
    if err!=nil {
        fmt.Fprintf(os.Stderr,"[Debug] [Error] Error while parsing flags from args %v: %v\n",flagsOnly,err)
        return finish()
    }
    if strings.HasPrefix(partial,"-") && !afterDash {
        if strings.Contains(partial,"=") { return finish() }
        descriptions:=flagDescriptions(cmd)
        for _,f:=range fs {
            if changed[f.name] { continue }
            names:=[]string{"--"+f.name}
            if f.short!="" { names=append(names,"-"+f.short) }
            for _,n:=range names { if strings.HasPrefix(n,partial) { items=append(items,completionItem{n,descriptions[f.name]}) } }
        }
        directive=4
        return finish()
    }
    children:=commandItems(cmd)
    if len(children)>0 && len(parsed.Args)==0 {
        directive=4
        for _,item:=range children { if strings.HasPrefix(item.Name,partial) { items=append(items,item) } }
    }
    return finish()
}
