package main

import (
    "reflect"
    "strings"
    "testing"
)

func TestParseProfilesAndAliases(t *testing.T) {
    text := "# local configuration\n127.0.0.1 localhost alias\n# 192.0.2.9 disabled\n"+
        "# profile.off dev\n# 192.0.2.1 app api\n192.0.2.2 db\n192.0.2.1 app other\n# end\n"
    h := parseHosts(strings.NewReader(text))
    got := h.Rows(nil,"list")
    want := []HostRow{
        {"default","on","127.0.0.1","localhost",0},
        {"default","off","192.0.2.9","disabled",0},
        {"dev","off","192.0.2.1","app",1},
        {"dev","off","192.0.2.1","api",1},
        {"dev","off","192.0.2.1","other",1},
        {"dev","off","192.0.2.2","db",1},
    }
    if !reflect.DeepEqual(got,want) { t.Fatalf("rows: %#v",got) }
    if rows:=h.Rows([]string{"missing"},"status");rows!=nil { t.Fatalf("missing rows: %#v",rows) }
    if rows:=h.Rows(nil,"enabled");len(rows)!=2 { t.Fatalf("implicit content should remain visible: %#v",rows) }
}

func TestNormalizationAndProfileOrder(t *testing.T) {
    h:=parseHosts(strings.NewReader("\n\n  # base  \n127.0.0.1 local alias\n\n# profile.on a\n1.1.1.1 old\n# end\n# profile.on b\n2.2.2.2 other\n# end\n"))
    h.Ensure("a",true).Add("3.3.3.3",[]string{"new"})
    want:="\n# base\n127.0.0.1 local\n\n"+divider+"\n"+managedNotice+"\n"+divider+"\n"+
        "\n# profile.on b\n2.2.2.2 other\n# end\n\n# profile.on a\n3.3.3.3 new\n# end\n"
    if got:=h.Encode();got!=want { t.Fatalf("serialized hosts:\n%q\nwant:\n%q",got,want) }
    if again:=parseHosts(strings.NewReader(want)).Encode();again!=want {t.Fatal("normalization should be idempotent")}
}

func TestEntrySyntax(t *testing.T) {
    cases:=[]struct{input,ip string;names []string}{
        {"#\t::ffff:192.0.2.1 first second # comment","192.0.2.1",[]string{"first","second"}},
        {"2001:0db8::001 server","2001:db8::1",[]string{"server"}},
        {"1.1.1.1 a\u00a0b","1.1.1.1",[]string{"a\u00a0b"}},
        {"1.1.1.1 a\vb","1.1.1.1",[]string{"a\vb"}},
        {"#192.0.2.1 name","",nil},
        {"192.000.2.1 name","",nil},
        {"1.1.1.1 # nothing","",nil},
    }
    for _,c:=range cases {
        ip,names:=parseEntry(c.input)
        if ip!=c.ip || !reflect.DeepEqual(names,c.names) { t.Errorf("parse %q: %q %#v",c.input,ip,names) }
    }
}

func TestRepeatedMarkersAndEmptyProfiles(t *testing.T) {
    h:=parseHosts(strings.NewReader("# profile.on x\n1.1.1.1 first\n# end\n# profile.off x\n# 2.2.2.2 last\n# end\n# profile.on empty\n# end\n"))
    rows:=h.Rows(nil,"list")
    if len(rows)!=2 || rows[0].Host!="last" || rows[1].Host!="last" || rows[0].Group==rows[1].Group {t.Fatalf("repeated marker groups: %#v",rows)}
    if got:=len(h.Rows(nil,"status"));got!=3 {t.Fatalf("profile statuses: %d",got)}
}
EOF
