)

func TestRenderFormats(t *testing.T) {
    rows:=[]HostRow{{"dev","on","1.2.3.4","test",1}}
    table:="+---------+--------+---------+--------+\n"+
        "| PROFILE | STATUS |   IP    | DOMAIN |\n"+
        "+---------+--------+---------+--------+\n"+
        "| dev     | on     | 1.2.3.4 | test   |\n"+
        "+---------+--------+---------+--------+\n"
    if got:=renderRows(rows,nil,"table",false,false);got!=table {t.Errorf("table:\n%q",got)}
    raw:="PROFILE\tSTATUS\tIP     \tDOMAIN \ndev    \ton    \t1.2.3.4\ttest  \t\n"
    if got:=renderRows(rows,nil,"raw",false,false);got!=raw {t.Errorf("raw:\n%q",got)}
    js:="[{\"Profile\":\"dev\",\"Status\":\"on\",\"IP\":\"1.2.3.4\",\"Host\":\"test\"}]\n"
    if got:=renderRows(rows,[]string{"ip"},"json",false,false);got!=js {t.Errorf("json: %q",got)}
    if got:=renderRows(nil,nil,"json",false,false);got!="null\n" {t.Errorf("empty json: %q",got)}
    if got:=renderRows(rows,[]string{"unknown"},"table",false,false);got!="" {t.Errorf("unknown column: %q",got)}
}

func TestDisplayWidthAndNumericAlignment(t *testing.T) {
    for s,w:=range map[string]int{"ascii":5,"café":4,"中文":4,"e\u0301":1,"👨\u200d👩\u200d👧":2,"\x1b[31mred\x1b[0m":3} {
        if got:=displayWidth(s);got!=w {t.Errorf("width %q = %d, want %d",s,got,w)}
    }
    for s,want:=range map[string]bool{"123":true,"-123":true,"1.5":true,"1,234.5":true,"12,34":false,"+12":false,".5":false,"127.0.0.1":false} {
        if got:=numberRE.MatchString(s);got!=want {t.Errorf("numeric %q = %t",s,got)}
    }
    lines:=wrapHeader(" "+strings.Repeat("x",35)+" ")
    if len(lines)!=3 || lines[0]!="" || lines[2]!="" {t.Errorf("wrapped header: %#v",lines)}
}
EOF
