package main

import (
    "strings"
    "testing"
    "time"
)

func TestOptionParsing(t *testing.T) {
    o,err:=parseOptions([]string{"--host-file","hosts","add","domains","dev","app","--ip=192.0.2.1","-w","2ms","-q","-c","ip,domain"},"/tmp")
    if err!=nil {t.Fatal(err)}
    if o.Command!="add domains" || o.IP!="192.0.2.1" || !o.Quiet || o.Wait!=2*time.Millisecond || len(o.Args)!=2 || len(o.Columns)!=2 {t.Fatalf("options: %#v",o)}
    if err:=validate(o);err!=nil {t.Fatal(err)}
}

func TestCLIValidation(t *testing.T) {
    cases:=[]struct{args []string;err string}{
        {[]string{"enable"},"missing profile name"},
        {[]string{"replace","a","b"},"specify only one profile"},
        {[]string{"add","domains","a","default"},"'default' profile should not be handled by hostctl"},
        {[]string{"remove","a","--all"},"args must be empty with --all flag"},
        {[]string{"backup","extra"},"accepts 0 arg(s), received 1"},
        {[]string{"list","--bad"},"unknown flag: --bad"},
        {[]string{"list","-qz"},"unknown shorthand flag: 'z' in -z"},
        {[]string{"---bad"},"bad flag syntax: ---bad"},
    }
    for _,c:=range cases {
        o,err:=parseOptions(c.args,"/tmp")
        if err==nil {err=validate(o)}
        if err==nil || err.Error()!=c.err {t.Errorf("%v: %v, want %q",c.args,err,c.err)}
    }
    _,err:=parseOptions([]string{"ls"},"/tmp")
    if err==nil || !strings.Contains(err.Error(),"Did you mean this?\n\tlist\n") {t.Errorf("suggestion: %v",err)}
}
EOF
cat > app_test.go <<'EOF'
package main

import (
    "os"
    "path/filepath"
    "testing"
    "time"
)

func TestStatefulProfileOperations(t *testing.T) {
    path:=filepath.Join(t.TempDir(),"hosts")
    if err:=os.WriteFile(path,[]byte("127.0.0.1 localhost aliases\n"),0644);err!=nil {t.Fatal(err)}
    run:=func(args ...string) {
        t.Helper()
        full:=append([]string{"--host-file",path,"-q"},args...)
        o,err:=parseOptions(full,"/tmp");if err!=nil {t.Fatal(err)}
        if err=(&Application{options:o,cwd:"/tmp"}).run();err!=nil {t.Fatal(err)}
    }
    run("add","domains","dev","app","api","--ip","192.0.2.1")
    run("disable","dev")
    run("add","domains","dev","third")
    h,err:=readHosts(path);if err!=nil {t.Fatal(err)}
    if !h.Profiles["dev"].Off || h.Profiles["dev"].Count()!=3 {t.Fatalf("profile: %#v",h.Profiles["dev"])}
    run("remove","domains","dev","app","api")
    run("toggle","dev")
    h,_=readHosts(path)
    if h.Profiles["dev"].Off || h.Profiles["dev"].Count()!=1 {t.Fatal("remove/toggle did not update profile")}
    run("remove","--all")
    h,_=readHosts(path)
    if len(h.Names)!=0 || len(h.Rows(nil,"list"))!=1 {t.Fatal("removal changed implicit hosts")}
}

func TestBackupAndRestore(t *testing.T) {
    dir:=t.TempDir();path:=filepath.Join(dir,"hosts")
    original:=[]byte("# original\r\n127.0.0.1 local aliases\r\n")
    os.WriteFile(path,original,0644)
    app:=&Application{options:&Options{HostFile:path,Path:dir,Quiet:true}}
    if err:=app.backup();err!=nil {t.Fatal(err)}
    backup:=filepath.Join(dir,"hosts"+time.Now().Format(".20060102"))
    copied,err:=os.ReadFile(backup);if err!=nil || string(copied)!=string(original) {t.Fatalf("backup: %q, %v",copied,err)}
    os.WriteFile(path,[]byte("changed\n"),0644)
    app.options.From=backup
    if err=app.restore();err!=nil {t.Fatal(err)}
    restored,_:=os.ReadFile(path);if string(restored)!=string(original) {t.Fatal("restore did not preserve bytes")}
    os.Remove(path)
    if err=app.restore();err==nil {t.Fatal("restore should require an existing hosts file")}
    if _,err=os.Stat(path);!os.IsNotExist(err) {t.Fatal("failed restore created a file")}
}

func TestComposeServiceSelectionData(t *testing.T) {
    services,err:=readCompose("version: '3'\nservices:\n  web:\n    image: nginx\n  db:\n    container_name: custom-db\n")
    if err!=nil || len(services)!=2 || services[1].ContainerName!="custom-db" {t.Fatalf("compose: %#v, %v",services,err)}
    flow,err:=readCompose("services: {web: {container_name: sample}}")
    if err!=nil || len(flow)!=1 || flow[0].ContainerName!="sample" {t.Fatalf("flow compose: %#v, %v",flow,err)}
}
EOF
